package ai.decisionos.aside;
import android.app.job.*;import android.content.*;import android.os.*;import android.webkit.*;import org.json.*;
/** Best-effort foreground-page DOM checks using the app WebView cookie jar. No account success assumed. */
public final class BlackboardNoticeMonitor extends JobService {
 static final int JOB=90601,NOW=90602;WebView web;JobParameters running;final Handler h=new Handler(Looper.getMainLooper());int generation;
 static boolean schedule(Context c,boolean now){try{JobInfo.Builder b=new JobInfo.Builder(now?NOW:JOB,new ComponentName(c,BlackboardNoticeMonitor.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY);if(now)b.setOverrideDeadline(10000);else b.setPersisted(true).setPeriodic(6L*60*60*1000);boolean ok=((JobScheduler)c.getSystemService(JOB_SCHEDULER_SERVICE)).schedule(b.build())==JobScheduler.RESULT_SUCCESS;if(!now)c.getSharedPreferences("nubi_blackboard_monitor",0).edit().putBoolean("enabled",ok).apply();return ok;}catch(Exception e){return false;}}
 static void stop(Context c){JobScheduler s=(JobScheduler)c.getSystemService(JOB_SCHEDULER_SERVICE);s.cancel(JOB);s.cancel(NOW);c.getSharedPreferences("nubi_blackboard_monitor",0).edit().putBoolean("enabled",false).apply();}
 public boolean onStartJob(JobParameters p){running=p;int gen=++generation;h.post(()->{web=new WebView(this);WebSessionPolicy.attach(web);web.measure(android.view.View.MeasureSpec.makeMeasureSpec(1080,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(1600,1073741824));web.layout(0,0,1080,1600);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient(){boolean queued;public void onPageFinished(WebView v,String url){WebSessionPolicy.checkpoint();if(!queued&&url.startsWith("https://blackboard.unist.ac.kr/")){queued=true;h.postDelayed(()->read(gen),10000);}}});h.postDelayed(()->finish(gen,"시간 초과 · Blackboard 로그인과 연결 확인 필요",true),35000);web.loadUrl("https://blackboard.unist.ac.kr/ultra/stream");});return true;}
 void read(int gen){if(gen!=generation||web==null)return;String script="(()=>{if(location.hostname!=='blackboard.unist.ac.kr'||[...document.querySelectorAll('input[type=password]')].some(e=>e.getClientRects().length))return JSON.stringify({state:'login'});let nodes=[...document.querySelectorAll('article,[role=listitem],.activity-item,.stream-entry')];let rows=nodes.map(e=>({title:(e.innerText||'').trim().slice(0,1500),url:location.href})).filter(e=>/(assignment|announcement|due|exam|test|message|과제|시험|공지|기한|팀플)/i.test(e.title)).slice(0,40);return JSON.stringify({state:rows.length?'ok':'unverified',rows})})()";web.evaluateJavascript(script,raw->{if(gen!=generation)return;try{JSONObject out=new JSONObject(new JSONArray("["+raw+"]").getString(0));if(!out.optString("state").equals("ok")){finish(gen,"Blackboard 읽기 미확인 · 로그인 또는 페이지 형식 확인 필요",true);return;}int count=0;try(CampusFlowStore store=new CampusFlowStore(this)){JSONArray rows=out.getJSONArray("rows");for(int n=0;n<rows.length();n++){JSONObject row=rows.getJSONObject(n);String title=row.getString("title"),id="bb-"+CampusNoticeMonitor.hash(title);if(!store.get(id).has("id")){GoalStore.put(row,"id",id);GoalStore.put(row,"service","blackboard");GoalStore.put(row,"text",title);GoalStore.put(row,"category",CampusWorkflows.category(title));store.save("observations",row);SchoolChatWork.publish(this,"blackboard",id,title,title,row.optString("url"),"");count++;}}}boolean baseline=getSharedPreferences("nubi_blackboard_monitor",0).getBoolean("baseline",false);getSharedPreferences("nubi_blackboard_monitor",0).edit().putBoolean("baseline",true).apply();if(baseline&&count>0)CampusNoticeMonitor.notifyChanges(this,count,"Blackboard에 새 과제·공지 후보가 있어요. 원문에서 기한과 조건을 확인해 주세요.");finish(gen,"Blackboard 읽기 확인 · 새 항목 "+count+"개",false);}catch(Exception e){finish(gen,"Blackboard 응답을 읽지 못했어요.",true);}});}
 void finish(int gen,String status,boolean retry){if(gen!=generation)return;generation++;getSharedPreferences("nubi_blackboard_monitor",0).edit().putString("status",status).putLong("checked",System.currentTimeMillis()).apply();h.removeCallbacksAndMessages(null);if(web!=null){web.stopLoading();web.destroy();web=null;}if(running!=null){jobFinished(running,retry);running=null;}}
 public boolean onStopJob(JobParameters p){generation++;h.removeCallbacksAndMessages(null);if(web!=null){web.destroy();web=null;}running=null;return true;}
}
